#!/usr/bin/env node
/** Real built App + session Django + synthetic SHA verified private media QA.
 * No external Drive; generated bytes are validated through the production
 * private API and React SourceLocator UI in Chromium. J6B synthetic-only.
 */
import assert from 'node:assert/strict';
import { createServer, request as httpRequest } from 'node:http';
import { readFileSync, mkdirSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

assert.equal(process.env.KT_J6B_ISOLATED, 'YES');
assert.equal(process.env.KT_J6B_WEB, 'http://127.0.0.1:62310');
assert.match(process.env.KT_J6B_API_URL||'', /^http:\/\/(?:172\.(?:1[6-9]|2\d|3[01])\.\d{1,3}\.\d{1,3}|127\.0\.0\.1):8152$/);
const targets={api:new URL(process.env.KT_J6B_API_URL),web:new URL(process.env.KT_J6B_WEB)};
const fixture=JSON.parse(readFileSync(process.env.KT_J6B_FIXTURE,'utf8'));
assert.equal(fixture.status,'prepared');
assert.equal(fixture.pdf_pages,3);
assert.equal(fixture.no_external_provider,true);
const out=path.resolve('tmp/p08-j6b-private');
mkdirSync(out,{recursive:true});
const {Browser}=await import(pathToFileURL(path.resolve('tools/smoke/p08_cdp.mjs')).href);
const sha=data=>createHash('sha256').update(data).digest('hex');
let proxy,browser;
const report={task:'P08/J6B',status:'NOT_RUN',scope:'REAL_APP_DJANGO_ISOLATED_SYNTHETIC_STORAGE',
  provider_drive:'NOT_RUN',native_android:'NOT_RUN',external_calls:0,
  pdf:{},mp4:{},foreign_owner_rejected:false,note_preserved:false};
try {
  proxy=createServer((req,res)=>{
    const target=req.url?.startsWith('/api/v1/')?targets.api:targets.web;
    const request=httpRequest({hostname:target.hostname,port:target.port,path:req.url,
      method:req.method,headers:{...req.headers,host:req.headers.host}},remote=>{
      res.writeHead(remote.statusCode||502,remote.headers);
      remote.pipe(res);
    });
    request.on('error',()=>{if(!res.headersSent)res.writeHead(502);res.end('qa bridge unavailable');});
    req.pipe(request);
  });
  await new Promise((resolve,reject)=>{proxy.once('error',reject);proxy.listen(0,'127.0.0.1',resolve);});
  const origin='http://127.0.0.1:'+proxy.address().port;
  assert.equal((await fetch(origin+'/api/v1/health')).status,200);
  browser=await Browser.launch({width:1440,height:960});
  const page=await browser.newPage({width:1440,height:960});
  await page.goto(origin+'/',{settleMs:600});
  const login=async username=>{
    const code=await page.eval(async user=>{
      const s=await fetch('/api/v1/session',{credentials:'same-origin'}).then(r=>r.json());
      const r=await fetch('/api/v1/session',{method:'POST',credentials:'same-origin',
        headers:{'Content-Type':'application/json','X-CSRFToken':s.csrf_token},
        body:JSON.stringify({username:user,password:'j6b-only-fixture-password'})});
      return r.status;
    },username);
    assert.equal(code,200,'QA session login');
  };
  await login('p08-j6b-owner');
  const get=async id=>page.eval(async itemId=>{
    const r=await fetch('/api/v1/items/'+itemId+'/knowledge',{credentials:'same-origin'});
    return {status:r.status,body:await r.json()};
  },id);
  const pdf=fixture.items.pdf;
  const knowledge=await get(pdf.item_id);
  assert.equal(knowledge.status,200);
  assert.equal(knowledge.body.parts.length,1);
  assert.equal(knowledge.body.parts[0].asset_id,pdf.asset_id);
  assert.equal(knowledge.body.parts[0].source.version,pdf.sha256);
  assert.equal(knowledge.body.parts[0].source.state,'current');
  assert.equal(knowledge.body.parts[0].locator.page,2);
  await page.goto(origin+'/#/muc/'+pdf.item_id,{settleMs:650});
  await page.eval(()=>new Promise((resolve,reject)=>{
    const until=Date.now()+12000;
    const poll=()=>{
      const button=[...document.querySelectorAll('.source-locator button')]
        .find(e=>e.textContent.includes('Mở và định vị PDF riêng tư'));
      if(button){button.click();return resolve(true);}
      if(Date.now()>until)return reject(Error('PDF_PAGE_ACTION_MISSING'));
      setTimeout(poll,60);
    };poll();
  }));
  const pdfResult=await page.eval(()=>new Promise((resolve,reject)=>{
    const until=Date.now()+16000;
    const poll=()=>{
      const img=document.querySelector('.source-locator-viewer img');
      const alert=document.querySelector('.source-locator [role=alert]');
      if(alert)return reject(Error('PDF_PAGE_ERROR '+alert.textContent));
      if(img?.complete&&img.naturalWidth>0&&img.naturalHeight>0){
        const canvas=document.createElement('canvas');
        canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;
        const ctx=canvas.getContext('2d',{willReadFrequently:true});
        ctx.drawImage(img,0,0);
        const color=Array.from(ctx.getImageData(Math.floor(canvas.width/2),
          Math.floor(canvas.height/2),1,1).data).slice(0,3);
        return resolve({color,width:canvas.width,height:canvas.height,alt:img.alt,
          state:document.querySelector('.source-locator')?.dataset.state});
      }
      if(Date.now()>until)return reject(Error('PDF_PAGE_IMAGE_TIMEOUT'));
      setTimeout(poll,60);
    };poll();
  }));
  assert.equal(pdfResult.alt,'Nội dung trang PDF số 2');
  assert.equal(pdfResult.state,'AVAILABLE');
  assert.ok(pdfResult.color[1]>230&&pdfResult.color[0]<30&&pdfResult.color[2]<30,
    'PDF page 2 must be GREEN in real Chromium pixels, not red or blue');
  await page.screenshot({path:path.join(out,'pdf-page2.png'),format:'png'});
  report.pdf={...pdfResult,source_sha256:pdf.sha256,page:2,
    proof:'actual pixels of PDFium-rendered authenticated SHA-pinned page two'};

  const mp4=fixture.items.mp4;
  const mp4Knowledge=await get(mp4.item_id);
  assert.equal(mp4Knowledge.status,200);
  assert.equal(mp4Knowledge.body.parts.length,1);
  assert.equal(mp4Knowledge.body.parts[0].source.version,mp4.sha256);
  assert.equal(mp4Knowledge.body.parts[0].locator.start_seconds,2.5);
  await page.goto(origin+'/#/muc/'+mp4.item_id,{settleMs:650});
  await page.eval(()=>new Promise((resolve,reject)=>{
    const until=Date.now()+12000;
    const poll=()=>{
      const button=[...document.querySelectorAll('.source-locator button')]
        .find(e=>e.textContent.includes('Mở và định vị nguồn riêng tư'));
      if(button){button.click();return resolve(true);}
      if(Date.now()>until)return reject(Error('MP4_ACTION_MISSING'));
      setTimeout(poll,60);
    };poll();
  }));
  const video=await page.eval(()=>new Promise((resolve,reject)=>{
    const until=Date.now()+18000;
    const poll=()=>{
      const video=document.querySelector('.source-locator-viewer video');
      const status=document.querySelector('.source-locator-viewer [role=status]')?.textContent||'';
      const alert=document.querySelector('.source-locator [role=alert]');
      if(alert)return reject(Error('MP4_ERROR '+alert.textContent));
      if(video&&status.startsWith('Đã đến'))return resolve({
        currentTime:video.currentTime,duration:video.duration,
        width:video.videoWidth,height:video.videoHeight,
        path:new URL(video.src).pathname,
        state:document.querySelector('.source-locator')?.dataset.state});
      if(Date.now()>until)return reject(Error('MP4_SEEK_TIMEOUT '+status));
      setTimeout(poll,60);
    };poll();
  }));
  assert.ok(Math.abs(video.currentTime-2.5)<=.3);
  assert.equal(video.width,320);assert.equal(video.height,180);
  assert.equal(video.state,'AVAILABLE');
  assert.equal(video.path,'/api/v1/assets/'+mp4.asset_id+'/content/1/'+mp4.sha256);
  const range=await page.eval(async uri=>{
    const r=await fetch(uri,{credentials:'same-origin',headers:{Range:'bytes=0-255'}});
    return {status:r.status,bytes:(await r.arrayBuffer()).byteLength,
      range:r.headers.get('Content-Range'),mime:r.headers.get('Content-Type'),
      cache:r.headers.get('Cache-Control')};
  },video.path);
  assert.equal(range.status,206);assert.equal(range.bytes,256);
  assert.equal(range.range,'bytes 0-255/'+mp4.size);
  assert.equal(range.mime,'video/mp4');assert.equal(range.cache,'private, no-store');
  await page.screenshot({path:path.join(out,'video-seek2_5.png'),format:'png'});
  report.mp4={...video,range,source_sha256:mp4.sha256,
    target_seconds:2.5,error_seconds:Math.abs(video.currentTime-2.5)};
  const pdfAfter=await get(pdf.item_id);
  const mp4After=await get(mp4.item_id);
  assert.equal(pdfAfter.body.text,'# Văn bản gốc P08 J6B pdf');
  assert.equal(mp4After.body.text,'# Văn bản gốc P08 J6B mp4');
  report.note_preserved=sha(Buffer.from(pdfAfter.body.text))===pdf.note_sha256&&
    sha(Buffer.from(mp4After.body.text))===mp4.note_sha256;
  assert.ok(report.note_preserved);
  const logout=await page.eval(async ()=>{
    const s=await fetch('/api/v1/session').then(r=>r.json());
    return (await fetch('/api/v1/session',{method:'DELETE',credentials:'same-origin',
      headers:{'X-CSRFToken':s.csrf_token}})).status;
  });
  assert.equal(logout,200);
  await login('p08-j6b-foreign');
  const privatePath='/api/v1/assets/'+pdf.asset_id+'/pdf-page/1/'+pdf.sha256+'/2';
  const denied=await page.eval(async uri=>(await fetch(uri,{credentials:'same-origin'})).status,privatePath);
  assert.equal(denied,404);
  report.foreign_owner_rejected=true;
  report.status='PASS_SYNTHETIC_PRIVATE_END_TO_END';
  report.synthetic_only=true;
  writeFileSync(path.join(out,'results.json'),JSON.stringify(report,null,2)+'\n');
  console.log(JSON.stringify({task:report.task,status:report.status,
    pdf_green:report.pdf.color,video_seconds:report.mp4.currentTime,
    owner_404:true,range_206:true,full_provider_drive:'NOT_RUN'}));
} finally {
  await browser?.close();
  if(proxy)await new Promise(resolve=>proxy.close(resolve));
}
